// 2-SAT SOLVER using Tarjan's SCC
// Variables: 0..n-1 (true), n..2n-1 (negated)
// For variable i: literal i = true, literal i+n = false (NOT i)
class TwoSAT {
    constructor(n) {
        this.n = n;
        this.adj  = Array.from({length:2*n}, ()=>[]);
        this.radj = Array.from({length:2*n}, ()=>[]); // reverse graph
    }

    // Add clause (x OR y): NOT x => y, NOT y => x
    addClause(x, y) {
        // x: positive literal is x, negative is x+n
        const notX = x < this.n ? x + this.n : x - this.n;
        const notY = y < this.n ? y + this.n : y - this.n;
        this.adj[notX].push(y);    // NOT x => y
        this.adj[notY].push(x);    // NOT y => x
        this.radj[y].push(notX);   // reverse
        this.radj[x].push(notY);
    }

    solve() {
        const n2 = 2 * this.n;
        // Kosaraju's 2-pass SCC (simpler to implement than Tarjan's here)
        const visited = new Array(n2).fill(false);
        const order = [];

        // DFS on original graph
        const dfs1 = (v) => {
            visited[v] = true;
            for (const u of this.adj[v]) if (!visited[u]) dfs1(u);
            order.push(v);
        };
        for (let v = 0; v < n2; v++) if (!visited[v]) dfs1(v);

        // DFS on reverse graph in reverse finish order
        const comp = new Array(n2).fill(-1);
        let sccId = 0;
        const dfs2 = (v, id) => {
            comp[v] = id;
            for (const u of this.radj[v]) if (comp[u] === -1) dfs2(u, id);
        };
        for (let i = n2 - 1; i >= 0; i--) {
            if (comp[order[i]] === -1) { dfs2(order[i], sccId); sccId++; }
        }

        // Check satisfiability and assign values
        const assignment = new Array(this.n);
        for (let i = 0; i < this.n; i++) {
            if (comp[i] === comp[i + this.n]) return null; // UNSAT
            assignment[i] = comp[i] > comp[i + this.n]; // higher SCC = true
        }
        return assignment;
    }
}

// TEST: (x0 OR x1) AND (NOT x0 OR x2) AND (NOT x1 OR NOT x2)
