// SPARSE TABLE for Range Minimum Query (RMQ) — O(n log n) build, O(1) query
class SparseTable {
    constructor(arr) {
        const n = arr.length;
        const LOG = Math.floor(Math.log2(n)) + 1;

        // Precompute log2 values to avoid Math.log2 in queries
        this.log2 = new Int32Array(n + 1);
        this.log2[1] = 0;
        for (let i = 2; i <= n; i++) this.log2[i] = this.log2[i>>1] + 1;

        // Build table: table[i][j] = min of arr[i..i+2^j-1]
        this.table = Array.from({length:n}, (_,i) => new Int32Array(LOG));
        for (let i = 0; i < n; i++) this.table[i][0] = arr[i];

        for (let j = 1; j < LOG; j++) {
            for (let i = 0; i + (1<<j) <= n; i++) {
                this.table[i][j] = Math.min(
                    this.table[i][j-1],
                    this.table[i + (1<<(j-1))][j-1]
                );
            }
        }
    }

    // Range Minimum Query [l, r] — O(1)
    query(l, r) {
        const k = this.log2[r - l + 1];
        return Math.min(this.table[l][k], this.table[r - (1<<k) + 1][k]);
    }
}

const arr = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3];
const st = new SparseTable(arr);
console.log(st.query(0, 9));  // 1 (min of entire array)
console.log(st.query(2, 5));  // 1 (min of [4,1,5,9])
console.log(st.query(6, 9));  // 2 (min of [2,6,5,3])

