// SQRT DECOMPOSITION for range sum with point updates
class SqrtDecomposition {
    constructor(arr) {
        this.n = arr.length;
        this.B = Math.ceil(Math.sqrt(this.n)); // block size
        this.arr = [...arr];
        this.blocks = new Array(Math.ceil(this.n / this.B)).fill(0);
        // Precompute block sums
        for (let i = 0; i < this.n; i++) {
            this.blocks[Math.floor(i / this.B)] += arr[i];
        }
    }

    // Point update: O(1)
    update(i, val) {
        this.blocks[Math.floor(i / this.B)] += val - this.arr[i];
        this.arr[i] = val;
    }

    // Range sum query [l, r]: O(sqrt n)
    query(l, r) {
        let sum = 0;
        const lBlock = Math.floor(l / this.B);
        const rBlock = Math.floor(r / this.B);

        if (lBlock === rBlock) {
            // Same block: scan elements directly
            for (let i = l; i <= r; i++) sum += this.arr[i];
        } else {
            // Left partial block
            for (let i = l; i < (lBlock+1)*this.B; i++) sum += this.arr[i];
            // Full blocks in middle
            for (let b = lBlock+1; b < rBlock; b++) sum += this.blocks[b];
            // Right partial block
            for (let i = rBlock*this.B; i <= r; i++) sum += this.arr[i];
        }
        return sum;
    }
}

const sq = new SqrtDecomposition([1,3,5,7,9,11,13,15,17]);
console.log(sq.query(0, 8)); // 81 (sum of all)
console.log(sq.query(1, 5)); // 35 (3+5+7+9+11)
sq.update(2, 10);            // change index 2 from 5 to 10
console.log(sq.query(1, 5)); // 40 (3+10+7+9+11)

// MO'S ALGORITHM — offline range queries in O(n sqrt n)
// Sort queries by (l/B, r) to minimise pointer movement
function mosAlgorithm(arr, queries) {
    const B = Math.ceil(Math.sqrt(arr.length));
    // Sort: by block of left endpoint, then by right endpoint
    const sortedQ = queries.map((q,i) => [...q, i]).sort((a,b) => {
        const blockA = Math.floor(a[0]/B), blockB = Math.floor(b[0]/B);
        if (blockA !== blockB) return blockA - blockB;
        return blockA % 2 === 0 ? a[1] - b[1] : b[1] - a[1]; // Hilbert curve variant
    });

    let curL = 0, curR = -1, curSum = 0;
    const results = new Array(queries.length);
    for (const [l, r, origIdx] of sortedQ) {
        while (curR < r) curSum += arr[++curR];
        while (curL > l) curSum += arr[--curL];
        while (curR > r) curSum -= arr[curR--];
        while (curL < l) curSum -= arr[curL++];
        results[origIdx] = curSum;
    }
    return results;
}
console.log(mosAlgorithm([1,3,5,7,9], [[0,2],[1,3],[2,4]])); // [9,15,21]

