// MEET IN THE MIDDLE — Partition Array into Two Equal Sum Halves
// Can we partition nums into two subsets with equal sum?
// n can be up to 40 (too large for O(2^40) bitmask DP)
function canPartitionMeetMiddle(nums) {
    const n = nums.length;
    const total = nums.reduce((a,b)=>a+b,0);
    if (total % 2 !== 0) return false;
    const target = total / 2;

    const half = Math.floor(n / 2);
    const left  = nums.slice(0, half);
    const right = nums.slice(half);

    // Enumerate all 2^half sums for left half
    const leftSums = [];
    for (let mask = 0; mask < (1 << left.length); mask++) {
        let sum = 0;
        for (let i = 0; i < left.length; i++)
            if (mask & (1<<i)) sum += left[i];
        leftSums.push(sum);
    }
    leftSums.sort((a,b)=>a-b);

    // For each right subset sum, check if (target - rightSum) is in leftSums
    for (let mask = 0; mask < (1 << right.length); mask++) {
        let sum = 0;
        for (let i = 0; i < right.length; i++)
            if (mask & (1<<i)) sum += right[i];
        const need = target - sum;
        // Binary search for need in leftSums
        let lo = 0, hi = leftSums.length - 1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (leftSums[mid] === need) return true;
            if (leftSums[mid] < need) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return false;
}

console.log(canPartitionMeetMiddle([1,5,11,5])); // true (1+5+5=11)
console.log(canPartitionMeetMiddle([1,2,3,5])); // false

// 4-SUM TARGET using meet-in-the-middle:
// Split into pairs (l1,l2) and (r1,r2)
// Enumerate all pair sums from each half
// For each pair sum from right half, binary search in sorted left pair sums
function fourSumExists(nums, target) {
    const n = nums.length;
    const leftPairs = [];
    for (let i=0;i<n;i++) for (let j=i+1;j<n;j++) leftPairs.push(nums[i]+nums[j]);
    leftPairs.sort((a,b)=>a-b);
    for (let i=0;i<n;i++) {
        for (let j=i+1;j<n;j++) {
            const need = target - nums[i] - nums[j];
            const idx = leftPairs.indexOf(need); // O(n^2) indexOf -- use binary search
            if (idx !== -1) return true;
        }
    }
    return false;
}

