// QUICKSELECT — O(n) expected time k-th smallest
function quickselect(arr, k) {
    const a = [...arr]; // copy to avoid modifying original
    return _quickselect(a, 0, a.length-1, k-1); // k-1 for 0-indexed
}

function _quickselect(arr, lo, hi, k) {
    if (lo === hi) return arr[lo];
    // Random pivot
    const pivotIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
    [arr[pivotIdx], arr[hi]] = [arr[hi], arr[pivotIdx]]; // move pivot to end
    const pivot = arr[hi];

    // Partition: Lomuto scheme
    let p = lo;
    for (let i = lo; i < hi; i++) {
        if (arr[i] <= pivot) { [arr[p], arr[i]] = [arr[i], arr[p]]; p++; }
    }
    [arr[p], arr[hi]] = [arr[hi], arr[p]]; // move pivot to final position

    if (p === k) return arr[p];
    if (p > k)  return _quickselect(arr, lo, p-1, k);
    else         return _quickselect(arr, p+1, hi, k);
}

console.log(quickselect([3,1,4,1,5,9,2,6], 3)); // 3rd smallest = 3 (sorted: 1,1,2,3,4,5,6,9)
console.log(quickselect([3,1,4,1,5,9,2,6], 1)); // 1st smallest = 1

// RESERVOIR SAMPLING — O(n) uniform sample of k from stream
function reservoirSample(stream, k) {
    const reservoir = stream.slice(0, k);
    for (let i = k; i < stream.length; i++) {
        const j = Math.floor(Math.random() * (i + 1));
        if (j < k) reservoir[j] = stream[i]; // replace with probability k/(i+1)
    }
    return reservoir;
}

// FISHER-YATES SHUFFLE — O(n) unbiased
function fisherYates(arr) {
    const a = [...arr];
    for (let i = a.length-1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i+1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}
console.log(fisherYates([1,2,3,4,5])); // random permutation

