  if(signal.includes('boolean')||signal.includes('2-sat')||signal.includes('constraint'))return'2-SAT';
  if(signal.includes('static range min')||signal.includes('rmq'))return'Sparse Table RMQ';
  if(signal.includes('n<=40')||signal.includes('subset'))return'Meet in the Middle';
  if(signal.includes('kth')||signal.includes('top k'))return'Quickselect';
  if(signal.includes('fallback')||signal.includes('sqrt'))return'Sqrt Decomposition';
  return'Unknown';
}

function module8Summary(){
  return{total:MODULE8.length,nc150:MODULE8.filter(p=>p.nc150).length};
}
